{
  "name": "TCA6408A 八位 I²C GPIO 扩展器",
  "name_en": "TCA6408A 8-bit I2C GPIO Expander",
  "manufacturer": "Texas Instruments",
  "description": "TCA6408A 是一款通过 I²C 接口提供 8 路可配置数字输入/输出的 GPIO 扩展芯片，常用于嵌入式原型、测试夹具和实验电路中扩展微控制器的数字引脚。它支持输入端口读取、输出端口控制、极性反转以及引脚方向配置。",
  "description_en": "The TCA6408A is an 8-bit GPIO expander that adds configurable digital input/output lines over an I2C interface. It is commonly used in embedded prototypes, test fixtures, and lab electronics to expand the digital I/O of a microcontroller, with support for input reading, output control, polarity inversion, and pin direction configuration.",
  "tag_hints": [
    "I2C GPIO expander",
    "8-bit digital I/O",
    "port expander",
    "input/output latch",
    "polarity inversion",
    "embedded prototyping"
  ],
  "actions": [
    {
      "action_name": "auto-reset",
      "description": "重置对 TCA6408A 通信的解析状态。",
      "description_en": "Reset the decoding state for TCA6408A communication."
    },
    {
      "action_name": "auto-start",
      "description": "开始一次新的 TCA6408A I²C 事务解析。",
      "description_en": "Start decoding a new TCA6408A I2C transaction."
    },
    {
      "action_name": "auto-flush",
      "description": "输出并清空当前累计的寄存器或逻辑状态信息。",
      "description_en": "Output and clear the currently accumulated register or logic-state information."
    },
    {
      "action_name": "auto-putx",
      "description": "输出一条已解析的寄存器或引脚状态信息。",
      "description_en": "Emit one decoded register or pin-state entry."
    },
    {
      "action_name": "auto-put_logic_states",
      "description": "输出 8 路 GPIO 当前逻辑状态。",
      "description_en": "Output the current logic states of the 8 GPIO lines."
    },
    {
      "action_name": "auto-handle_reg_0x00",
      "description": "解析输入端口寄存器（0x00）。",
      "description_en": "Decode the input port register (0x00)."
    },
    {
      "action_name": "auto-handle_reg_0x01",
      "description": "解析输出端口寄存器（0x01）。",
      "description_en": "Decode the output port register (0x01)."
    },
    {
      "action_name": "auto-handle_reg_0x02",
      "description": "解析极性反转寄存器（0x02）。",
      "description_en": "Decode the polarity inversion register (0x02)."
    },
    {
      "action_name": "auto-handle_reg_0x03",
      "description": "解析配置寄存器（0x03）。",
      "description_en": "Decode the configuration register (0x03)."
    },
    {
      "action_name": "auto-handle_write_reg",
      "description": "处理对所选寄存器的写入数据。",
      "description_en": "Handle data written to the selected register."
    },
    {
      "action_name": "auto-check_correct_chip",
      "description": "检查 I²C 地址是否对应 TCA6408A 器件。",
      "description_en": "Check whether the I2C address matches a TCA6408A device."
    },
    {
      "action_name": "auto-decode",
      "description": "解码 TCA6408A 的 I²C 总线事务并识别寄存器访问。",
      "description_en": "Decode TCA6408A I2C bus transactions and identify register accesses."
    }
  ]
}

